using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.Linq;using System.IO;using System.Collections.Generic;
public static class FitStorageInteriors {
static Material White=>AssetDatabase.LoadAssetAtPath<Material>("Assets/Labs/Upgrade/Materials/White.mat");
static void Panel(Transform root,string name,Vector3 p,Vector3 size){var o=GameObject.CreatePrimitive(PrimitiveType.Cube);o.name=name;o.transform.SetParent(root,true);o.transform.position=p;o.transform.localScale=size;o.GetComponent<Renderer>().sharedMaterial=White;}
static LabFixture Drawer(Transform parent,string model,string name,Vector3 p,Quaternion q,Vector3 travel,LabFixture[] doors){var pivot=new GameObject(name);pivot.transform.SetParent(parent,true);pivot.transform.SetPositionAndRotation(p,q);var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Labs/Upgrade/StorageDrawers.fbx").GetComponentsInChildren<Transform>().First(t=>t.name==model);var body=Object.Instantiate(source.gameObject);body.transform.SetParent(pivot.transform,false);body.transform.localPosition=Vector3.zero;body.transform.localRotation=Quaternion.identity;foreach(var r in body.GetComponentsInChildren<MeshRenderer>()){r.sharedMaterial=White;r.gameObject.AddComponent<MeshCollider>().sharedMesh=r.GetComponent<MeshFilter>().sharedMesh;}var f=pivot.AddComponent<LabFixture>();f.action=LabFixture.Action.Drawer;f.movingPart=pivot.transform;f.openOffset=travel;f.label="Open / close storage tray";f.requiredOpen=doors;return f;}
public static void Run(){if(EditorApplication.isPlaying||Lightmapping.isRunning)throw new System.Exception("Idle required");AssetDatabase.Refresh();var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene().path;Directory.CreateDirectory("../Backups/BeforeFittedInteriors");try{foreach(var room in new[]{"Chemistry","Biology","Engineering"}){var scene=EditorSceneManager.OpenScene("Assets/Labs/Scenes/"+room+".unity");if(GameObject.Find(room+" coordinated interiors"))continue;if(!File.Exists("../Backups/BeforeFittedInteriors/"+room+".unity"))File.Copy(scene.path,"../Backups/BeforeFittedInteriors/"+room+".unity");var storage=GameObject.Find(room=="Chemistry"?"Chemistry fitted furniture":room+" working storage");var root=new GameObject(room+" coordinated interiors").transform;root.SetParent(storage.transform,true);string prefix=room=="Chemistry"?"CHEM-GLASS":room=="Biology"?"BIO-STORE":"ENG-STORE";var doors=storage.GetComponentsInChildren<LabFixture>().Where(f=>f.name.StartsWith(prefix+"-door")).ToArray();if(doors.Length!=2)throw new System.Exception("Expected two cabinet doors "+room);var drawers=new List<LabFixture>();
if(room=="Chemistry"){
foreach(var r in Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name.StartsWith(prefix+"-shelf")).ToArray())Object.DestroyImmediate(r.gameObject);
Panel(root,"Kit centre divider",new Vector3(.267f,1.096f,.725f),new Vector3(.49f,1.958f,.018f));
foreach(float y in new[]{1.26f,1.65f})Panel(root,"Tall kit upper shelf",new Vector3(.267f,y,1.03f),new Vector3(.49f,.018f,.58f));
for(int i=0;i<4;i++)drawers.Add(Drawer(root,"ChemistryTray","CHEM kit tray "+i,new Vector3(.49f,.38f+i*.32f,.423f),Quaternion.Euler(0,90,0),new Vector3(.24f,0,0),doors));
}else if(room=="Biology"){
drawers.Add(Drawer(root,"BiologyRulerDrawer","BIO 1.09m clear ruler drawer",new Vector3(3.175f,1.45f,.505f),Quaternion.identity,new Vector3(0,0,.26f),doors));
}else{
foreach(var r in Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name.StartsWith(prefix+"-shelf")&&r.bounds.center.y<1).ToArray())Object.DestroyImmediate(r.gameObject);
Panel(root,"Stand bay divider",new Vector3(3.635f,.552f,.275f),new Vector3(.018f,.87f,.50f));
Panel(root,"Full width long-tool shelf",new Vector3(3.35f,1.0f,.275f),new Vector3(1.35f,.018f,.51f));
foreach(float y in new[]{.45f,.85f})Panel(root,"Short kit shelf",new Vector3(3.15f,y,.275f),new Vector3(.95f,.018f,.51f));
for(int i=0;i<2;i++)drawers.Add(Drawer(root,"ChemistryTray","ENG small-parts tray "+i,new Vector3(3.15f,.29f+i*.32f,.505f),Quaternion.identity,new Vector3(0,0,.24f),doors));
}
foreach(var door in doors)door.closeBeforeClosing=drawers.ToArray();PrefabUtility.SaveAsPrefabAsset(storage,"Assets/Labs/Upgrade/"+room+"WorkingStorage.prefab");EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Debug.Log(room+" coordinated storage saved");}}finally{EditorSceneManager.OpenScene(original);}}}
